function toast(text, error = false) { const el = $('#toast'); el.textContent = text; el.className = `visible ${error?'error-toast':''}`; clearTimeout(toastTimer); toastTimer=setTimeout(()=>el.className='',6500); }
async function api(path, options = {}) {
  const headers = {'X-ASH-Client':'web',...options.headers};
  if(options.body && !(options.body instanceof Blob)) headers['Content-Type']='application/json';
  if(options.method && options.method!=='GET') headers['X-CSRF-Token']=S.csrf;
  const response = await fetch(`/api${path}`, {...options,headers,credentials:'same-origin'});
  if(!response.ok) {
    let payload; try { payload=await response.json(); } catch { payload={detail:'ارتباط سرور ناموفق بود.'}; }
    if(response.status===401 && path!=='/auth/login') resetLogin();
    const message=Array.isArray(payload.detail) ? payload.detail.map(e=>`${e.loc.slice(1).join('.')}: ${e.msg}`).join('؛ ') : payload.detail;
    throw new Error(message || 'عملیات ناموفق بود.');
  }
  return options.download ? response.blob() : response.json();
}
function resetLogin() { ++navVersion; Object.assign(S,{user:null,csrf:'',patients:[],rx:[],orders:[],admissions:[],medicines:[],users:[],logs:[]}); closeModal(); $('#print-root').innerHTML=''; if(window.ASHWorkspace)window.ASHWorkspace.reset(); if(window.ASHProfessional)window.ASHProfessional.reset(); loginView(); }
