function head(title, description, actions='') {return `<div class="section-head"><div><div class="eyebrow en">ASH NEXUS / ${S.page.toUpperCase()}</div><h1>${title}</h1><p>${description}</p></div><div class="row">${actions}</div></div>`;}
function empty(title, message, button='') {return `<div class="empty">${icon('rx')}<h3>${title}</h3><p>${message}</p>${button}</div>`;}
const action = (name,label,ic='plus',extra='',secondary=false) => `<button class="btn ${secondary?'secondary':''}" data-action="${name}" ${extra}>${icon(ic)}${label}</button>`;
const statsCard=(label,value,ic,foot)=>`<div class="card stat"><small>${label}</small><div class="icon-box">${icon(ic)}</div><strong>${number(value)}</strong><div class="stat-foot">${foot}</div></div>`;
async function navigate(page) {
  if(!availableNav().some(n=>n[0]===page)) return;
  closeModal(); S.page=page; const token=++navVersion;
  $$('.nav-link').forEach(n=>n.classList.toggle('active',n.dataset.page===page));
  $('#breadcrumb').textContent=navItems.find(n=>n[0]===page)[2]; $('#sidebar').classList.remove('open');
  $('#page-content').innerHTML='<div class="spinner">در حال دریافت اطلاعات از دیتابیس…</div>';
  try {
    let data;
    if(page==='dashboard') data=await api('/dashboard');
    if(page==='patients') data=await api('/patients');
    if(page==='rx') data=await api('/prescriptions');
    if(page==='pharmacy') data=await api('/medicines');
    if(page==='lab'||page==='radiology') data=await api(`/orders?kind=${page}`);
    if(page==='beds') data=await api('/admissions');
    if(page==='users') data=await api('/auth/users');
    if(page==='audit') data=await api('/audit');
    if(page==='settings') data=await api('/activation');
    if(window.ASHWorkspace) data=await window.ASHWorkspace.load(page,data);
    if(window.ASHProfessional) data=await window.ASHProfessional.load(page,data);
    if(token!==navVersion||!S.user) return;
    if(page==='dashboard') S.stats=data;
    if(page==='patients') S.patients=data;
    if(page==='rx') S.rx=data;
    if(page==='pharmacy') S.medicines=data;
    if(page==='lab'||page==='radiology') S.orders=data;
    if(page==='beds') S.admissions=data;
    if(page==='users') S.users=data;
    if(page==='audit') S.logs=data;
    if(page==='settings') S.activation=data;
    if(window.ASHWorkspace) window.ASHWorkspace.accept(page,data);
    $('#page-content').innerHTML=(S.demo?'<div class="notice">محیط آزمایشی: تمام داده‌های نمونه ساختگی است؛ برای مریض واقعی استفاده نکنید.</div>':'')+views[page]();
    window.scrollTo({top:0,behavior:'smooth'});
  } catch(error) {if(token===navVersion&&S.user) $('#page-content').innerHTML=`<div class="notice">${esc(error.message)} <button class="btn ghost" data-page="${page}">دوباره کوشش کنید</button></div>`;}
}
