function patientRows() { return S.patients.map(p=>`<tr><td><strong>${esc(p.first_name)} ${esc(p.last_name)}</strong><small>${esc(p.father_name)}</small></td><td><span class="en">${p.mrn}</span></td><td>${number(p.age)} سال · ${p.sex==='male'?'مرد':p.sex==='female'?'زن':'نامشخص'}</td><td><span class="en">${esc(p.phone)||'—'}</span></td><td><span class="tag ${p.allergies?'gold':'gray'}">${p.allergies?'ثبت حساسیت':'ثبت نشده'}</span></td><td>${can('admin','doctor')?`<button class="btn ghost small" data-action="workspace-dossier" data-id="${p.id}">${icon('patients')} نمای دوسیه</button>`:''}<button class="btn ghost small" data-action="patient-edit" data-id="${p.id}">دوسیه</button>${can('doctor')?`<button class="btn ghost small" data-action="rx-new" data-id="${p.id}">نسخه ${icon('arrow')}</button>`:''}</td></tr>`).join(''); }
function patientsView() {return head('مریضان و معاینات','شناسهٔ یکتا، مشخصات و سابقهٔ هر مریض.',action('patient-new','ثبت مریض'))+`<div class="card"><form class="toolbar" id="patient-search"><label class="search">${icon('search')}<input name="q" placeholder="جستجوی نام، تخلص یا شناسهٔ مریض" maxlength="100" aria-label="جستجوی مریض"></label><button class="btn secondary small" type="submit">جستجو</button></form><div class="table-wrap"><table><thead><tr><th>مریض</th><th>شناسهٔ سیستم</th><th>سن و جنس</th><th>تماس</th><th>حساسیت</th><th>عملیات</th></tr></thead><tbody id="patient-rows">${patientRows()}</tbody></table></div><div id="patient-empty">${S.patients.length?'':empty('هنوز مریضی ثبت نشده','از ثبت مریض شروع کنید یا با نام/شناسه جستجو کنید.')}</div><div class="table-bottom">نمایش حداکثر ۱۰۰ نتیجه؛ برای یافتن دوسیه‌های دیگر جستجو کنید.</div></div>`;}
function rxView() {return head('نسخه‌های طبی','پیش‌نویس با نسخهٔ تأییدشده متفاوت است؛ تصمیم نهایی با داکتر.',can('doctor')?action('rx-new','نسخهٔ جدید'):'')+`<div class="card"><div class="card-title"><h3>نسخه‌های ذخیره‌شده</h3><span class="tag gray">آخرین ۲۰۰ نسخه</span></div>${S.rx.length?`<div class="table-wrap"><table><thead><tr><th>شماره</th><th>مریض</th><th>داکتر</th><th>تاریخ</th><th>وضعیت</th><th></th></tr></thead><tbody>${S.rx.map(r=>`<tr><td class="en">RX-${String(r.id).padStart(6,'0')}</td><td><strong>${esc(r.patient.first_name)} ${esc(r.patient.last_name)}</strong><small class="en">${r.patient.mrn}</small></td><td>${esc(r.doctor)}</td><td>${date(r.created)}</td><td><span class="tag ${r.status==='draft'?'gold':''}">${r.status==='draft'?'پیش‌نویس':'تأیید داکتر'}</span></td><td><button class="btn ghost small" data-action="rx-preview" data-id="${r.id}">${icon('print')} مشاهده و چاپ</button></td></tr>`).join('')}</tbody></table></div>`:empty('نسخه‌ای وجود ندارد','داکتر می‌تواند نسخه را ذخیره، بازبینی و سپس تأیید کند.')}</div>`;}
function pharmacyView() {return head('داشبورد دواخانه','فهرست دوا و تغییر موجودی با ثبت رویداد؛ بدون دوزدهی خودکار.',can('admin','pharmacy')?action('medicine-new','ثبت قلم دوا'):'')+`<div class="card"><div class="card-title"><h3>موجودی دوا</h3><span class="tag gray">حداکثر ۱۰۰۰ قلم</span></div>${S.medicines.length?`<div class="table-wrap"><table><thead><tr><th>نام دوا</th><th>شکل و قدرت</th><th>موجودی</th><th>حد سفارش</th><th>وضعیت</th><th></th></tr></thead><tbody>${S.medicines.map(m=>`<tr><td>${esc(m.name)}</td><td>${esc(m.form)} · ${esc(m.strength)}</td><td>${number(m.stock)}</td><td>${number(m.reorder)}</td><td><span class="tag ${m.stock<=m.reorder?'gold':''}">${m.stock<=m.reorder?'نیاز به سفارش':'موجود'}</span></td><td>${can('admin','pharmacy')?`<button class="btn ghost small" data-action="stock" data-id="${m.id}">تغییر موجودی</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:empty('فهرست دوا خالی است','مسئول دواخانه اقلام و موجودی واقعی را وارد می‌کند.')}</div><div class="notice" style="margin-top:20px">این بخش فعلاً موجودی ساده است؛ مدیریت بچ/انقضا، فروش، قیمت‌گذاری و تحویل نسخه هنوز پیاده نشده‌اند.</div>`;}
function ordersView() {const title=S.page==='lab'?'لابراتوار':'اکسری';return head(`داشبورد ${title}`,'درخواست داکتر و ثبت نتیجه توسط بخش مسئول.',can('doctor')?action('order-new','درخواست جدید'):'')+`<div class="card"><div class="card-title"><h3>درخواست‌های معاینات</h3><span class="tag gray">آخرین ۲۰۰ درخواست</span></div>${S.orders.length?`<div class="table-wrap"><table><thead><tr><th>مریض</th><th>درخواست</th><th>تاریخ</th><th>وضعیت</th><th></th></tr></thead><tbody>${S.orders.map(o=>`<tr><td><strong>${esc(o.patient_name)}</strong><small class="en">${o.mrn}</small></td><td>${esc(o.title)}</td><td>${date(o.created)}</td><td><span class="tag ${o.status==='requested'?'gold':''}">${o.status==='requested'?'در انتظار نتیجه':'نتیجه ثبت شد'}</span></td><td><button class="btn ghost small" data-action="order-open" data-id="${o.id}">${o.status==='completed'?'مشاهدهٔ نتیجه':can(S.page)?'ثبت نتیجه':'جزئیات'}</button></td></tr>`).join('')}</tbody></table></div>`:empty('درخواستی ثبت نشده','داکتر درخواست می‌دهد؛ نتیجه فقط توسط کاربر بخش مربوط ثبت می‌شود.')}</div>`;}
function bedsView() {const active=S.admissions.filter(a=>!a.discharged);return head('بستری و بسترها','ظرفیت ده بستر؛ جلوگیری از اشغال هم‌زمان یک بستر یا بستری تکراری.',can('doctor','admin')?action('admit-new','ثبت بستری'):'')+`<div class="card card-pad"><div class="section-head"><h3>وضعیت بسترها</h3><span class="tag">${number(10-active.length)} بستر آزاد</span></div><div class="bed-grid">${Array.from({length:10},(_,i)=>{const a=active.find(a=>a.bed===i+1);return `<div class="bed ${a?'occupied':''}">${icon('beds')}<b>بستر ${number(i+1)}</b><small>${a?esc(a.patient_name):'آمادهٔ پذیرش'}</small>${a&&can('doctor')?`<br><button class="btn ghost small" data-action="discharge" data-id="${a.id}">ترخیص</button>`:''}</div>`;}).join('')}</div></div><div class="card" style="margin-top:22px"><div class="card-title"><h3>سوابق بستری</h3><span class="tag gray">فعال‌ها و حداکثر ۲۱۰ سابقه</span></div>${S.admissions.length?`<div class="table-wrap"><table><thead><tr><th>مریض</th><th>بستر</th><th>علت بستری</th><th>وضعیت</th></tr></thead><tbody>${S.admissions.map(a=>`<tr><td>${esc(a.patient_name)}</td><td>${number(a.bed)}</td><td>${esc(a.reason)}${a.discharged?`<br><small>ترخیص: ${esc(a.discharge_note)}</small>`:''}</td><td><span class="tag ${a.discharged?'gray':'gold'}">${a.discharged?'ترخیص‌شده':'بستری'}</span></td></tr>`).join('')}</tbody></table></div>`:empty('بستری ثبت نشده','تخصیص بستر و یادداشت ترخیص در دیتابیس ذخیره می‌شود.')}</div>`;}
function templateMini(t) {return `<div class="mini-document"><div class="mini-head"><span class="mini-cross">+</span><div><b>${esc(S.hospital.name||"شفاخانهٔ ایبک")}</b><small class="en">${esc(S.hospital.english_name||"AYBEK HOSPITAL")}</small></div></div><div class="mini-lines">${Array.from({length:11},()=>'<i></i>').join('')}</div><span class="mini-rx">℞</span><div class="mini-footer">تماس · آدرس · تأیید داکتر</div></div>`;}
function templateClass(t) {return `${t.studio?'studio-'+t.studio.family+(t.studio.compact?' studio-compact':''):''} ornament-${t.ornament||'plain'} typography-${t.typography||'sans'} header-${t.header} border-${t.border} table-${t.table} footer-${t.footer} density-${t.density} layout-${t.slug}`;}
function templatesView() {return head('استودیوی دیزاین اسناد','۲۰۰ چیدمان A4؛ تغییر ساختار هدر، قاب، جدول، فاصله‌ها و فوتر.')+`<div class="notice teal" style="margin-bottom:23px">${can('admin')?'انتخاب یک طرح، قالب پیش‌فرض شفاخانه را در دیتابیس ذخیره می‌کند.':'انتخاب طرح برای نسخهٔ جدید شما در همین نشست اعمال می‌شود.'} اطلاعات نسخه در همهٔ طرح‌ها ثابت می‌ماند. پیش‌نمایش واقعی از نسخهٔ ذخیره‌شده در بخش نسخه‌ها قابل چاپ است.</div><div class="template-grid">${S.templates.map(t=>`<button class="template-card ${templateClass(t)} ${S.selectedTemplate===t.id?'selected':''}" style="--accent:${t.color}" data-action="template-select" data-id="${t.id}">${templateMini(t)}<div class="template-label"><b>${esc(t.name)}</b><span class="tag gray">${number(t.id)}</span></div><span class="muted tiny">${S.selectedTemplate===t.id?'طرح انتخاب‌شده':'انتخاب چیدمان'} · A4</span></button>`).join('')}</div>`;}
function field(label,name,type='text',value='',attrs='') {return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;}
function area(label,name,value='',attrs='') {return `<label class="field full">${label}<textarea name="${name}" ${attrs}>${esc(value)}</textarea></label>`;}
function hospitalForm() {const h=S.hospital;return `<form id="hospital-form" class="card card-pad"><div class="form-grid">${field('نام دری شفاخانه','name','text',h.name,'required maxlength="200"')}${field('نام انگلیسی','english_name','text',h.english_name,'dir="ltr" maxlength="200"')}${field('خدمات شفاخانه','services','text',h.services,'maxlength="300"')}${field('نمبر تماس','phone','text',h.phone,'dir="ltr" maxlength="100"')}${field('ایمیل','email','email',h.email,'dir="ltr" maxlength="150"')}${field('وب‌سایت','website','text',h.website,'dir="ltr" maxlength="150"')}${area('آدرس','address',h.address,'maxlength="300"')}<label class="field">طرح پیش‌فرض<select name="template_id">${S.templates.map(t=>`<option value="${t.id}" ${h.template_id===t.id?'selected':''}>${t.name}</option>`).join('')}</select></label></div><div class="form-actions"><button type="submit" class="btn">${icon('check')} ذخیره در دیتابیس</button></div></form>`;}
function activationPanel(){const a=S.activation;return `<div class="card card-pad" style="margin-bottom:22px"><div class="row between"><h3>وضعیت راه‌اندازی و فعال‌سازی</h3><span class="tag ${a.status==='needs_review'?'gold':''}">${a.status==='needs_review'?'نیاز به بازبینی':'راه‌اندازی کامل'}</span></div><p>${esc(a.message||(a.commercial_license?'فایل فعال‌سازی امضاشده ثبت شده است.':'فعال‌سازی محلی؛ بدون لایسنس تجاری اجباری.'))}</p>${a.installation_id?`<div class="tiny en">${esc(a.installation_id)}</div>`:''}${a.commercial_license?`<p class="tiny">${esc(a.organization)} · ${a.expires_at?'انقضا: '+date(a.expires_at):'بدون انقضای ثبت‌شده'}</p><label class="field">تمدید با فایل صادرکننده<input type="file" id="activation-file" accept=".ashlicense,.json"></label>`:''}</div>`;}
function usersView() {return head('کاربران و سطح دسترسی','حساب جدا برای هر کارمند؛ حساب مشترک استفاده نکنید.',action('user-new','کاربر جدید'))+`<div class="card"><div class="table-wrap"><table><thead><tr><th>نام</th><th>نام کاربری</th><th>نقش</th><th>وضعیت</th><th></th></tr></thead><tbody>${S.users.map(u=>`<tr><td>${esc(u.name)}</td><td class="en">${esc(u.username)}</td><td>${roles[u.role]}</td><td><span class="tag ${u.active?'':'gray'}">${u.active?'فعال':'غیرفعال'}</span></td><td>${u.active&&u.role!=='admin'?`<button class="btn ghost small" data-action="user-deactivate" data-id="${u.id}">غیرفعال‌سازی</button>`:''}</td></tr>`).join('')}</tbody></table></div></div><div class="notice" style="margin-top:20px">ثبت نسخه و درخواست معاینه مخصوص حساب داکتر است. حساب مدیر به‌خودی‌خود صلاحیت طبی ندارد. ثبت نتیجه نیز فقط توسط نقش لابراتوار یا اکسری انجام می‌شود.</div>`;}
function backupView() {return head('بکاپ و بازیابی','Snapshot سازگار SQLite؛ بدون کپی خام دیتابیس در حال نوشتن.')+`<div class="cols"><div class="card card-pad"><div class="tag">${icon('shield')} دسترسی مخصوص مدیر</div><h2 style="margin-top:23px">یک نسخهٔ قابل‌بازیابی، نه فقط یک فایل.</h2><p>بکاپ شامل داده‌های مریضان، حساب‌ها و رویدادهاست. نشست‌های ورود از فایل پشتیبان حذف می‌شوند. دانلود فقط پس از تأیید درخواست مدیر انجام می‌شود.</p><div class="notice">این فایل رمزگذاری‌شده نیست. قبل از انتقال، آن را روی فضای رمزگذاری‌شده و محدود به افراد مجاز نگهداری کنید. هرگز فایل را در Git یا گفت‌وگو آپلود نکنید.</div><div class="form-actions">${action('backup-download','ساخت و دانلود بکاپ','backup')}</div></div><div class="card card-pad"><h3>بازیابی ایمن</h3><ol class="guide-list"><li>فایل بکاپ مورد اعتماد را انتخاب کنید.</li><li>با دستور زیر در یک مسیر جدید بازیابی کنید.</li><li>سرور را متوقف و مسیر دیتابیس جدید را تنظیم کنید.</li><li>ورود، تعداد دوسیه‌ها و چاپ را بررسی کنید.</li></ol><div class="code">python -m scripts.manage restore backup.sqlite3 .data/restored.sqlite3</div><p class="tiny">روی دیتابیس موجود بازنویسی نمی‌شود. این نسخه بکاپ زمان‌بندی‌شده و مدیریت ضمیمه‌ها ندارد.</p></div></div>`;}
function auditView() {return head('ثبت رویدادهای سیستم','آخرین ۲۰۰ رویداد؛ بدون ثبت رمز یا متن نسخه در لاگ.')+`<div class="card"><div class="table-wrap"><table><thead><tr><th>شناسه</th><th>کاربر</th><th>رویداد</th><th>مرجع</th><th>زمان</th></tr></thead><tbody>${S.logs.map(l=>`<tr><td>${number(l.id)}</td><td>${l.actor?number(l.actor):'سیستم'}</td><td class="en">${esc(l.action)}</td><td>${esc(l.resource)}</td><td>${date(l.created)}</td></tr>`).join('')}</tbody></table></div></div>`;}
function guideView() {return head('راهنمای کار با سیستم','مرز قابلیت‌های فعلی روشن است؛ هیچ تشخیص یا درمان خودکار پنهانی وجود ندارد.')+`<div class="stack"><div class="card card-pad"><h2>از کجا شروع کنم؟</h2><ol class="guide-list"><li>مدیر: نام شفاخانه و اطلاعات چاپ را در پروفایل تنظیم کنید.</li><li>برای داکتر، پذیرش، دواخانه، لابراتوار و اکسری حساب جدا بسازید.</li><li>پذیرش: مریض را ثبت کنید و شناسهٔ یکتا را یادداشت کنید.</li><li>داکتر: مریض را انتخاب و شکایت، تشخیص و دوا را خودتان وارد کنید.</li><li>بازبینی محدود را اجرا کنید؛ آن را تضمین صحت یا نبود تداخل ندانید.</li><li>نسخه را ذخیره، مرور، تأیید و سپس روی کاغذ A4 چاپ کنید.</li><li>از داده‌های آزمایشی بکاپ بگیرید و بازیابی در مسیر جدید را آزمایش کنید.</li></ol></div><div class="grid2"><div class="card card-pad"><h3>دستیار طبی فعلی چه می‌کند؟</h3><p>تکمیل واژهٔ اعراض از یک فهرست کوچک، یادآوری حساسیت و سن اطفال، بررسی نام تکراری دوا و هشدار محدود وارفارین/اسپرین. تشخیص، دوزدهی، شناسایی جامع تداخلات، پیشنهاد درمان و سفارش خودکار معاینه انجام نمی‌دهد.</p><div class="notice">دوا، سیرم یا آمپول اجباری در نسخه وجود ندارد. مسئولیت ارزیابی و تأیید بالینی با داکتر است.</div></div><div class="card card-pad"><h3>چه چیز هنوز آماده نیست؟</h3><p>هوش مصنوعی بالینی اعتبارسنجی‌شده، موتور دانش جامع، جراحی و بیهوشی، حسابداری، HL7/FHIR، مدیریت انقضا و بچ دوا، ضمیمه/تصویر، بکاپ خودکار، نصب‌کنندهٔ مستقل و مجوز استفادهٔ بالینی هنوز فراهم نشده‌اند.</p><p>اسناد نصب ویندوز، تست‌ها و محدودیت‌ها در <span class="en">docs/SETUP_FA.md</span> قرار دارند. تمام assetهای این رابط محلی هستند؛ مدل ابری یا فونت اینترنتی بارگیری نمی‌شود.</p></div></div></div>`;}
const views={dashboard:dashboardView,patients:patientsView,rx:rxView,pharmacy:pharmacyView,lab:ordersView,radiology:ordersView,beds:bedsView,templates:templatesView,settings:()=>head('پروفایل شفاخانه','اطلاعات مشترک هدر و فوتر چاپ؛ تغییرات در دیتابیس ذخیره می‌شود.')+activationPanel()+hospitalForm(),users:usersView,backup:backupView,audit:auditView,guide:guideView};
function showModal(title,html,wide=false) {previousFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section role="dialog" aria-modal="true" aria-labelledby="modal-title" class="modal ${wide?'wide':''}" tabindex="-1"><header class="modal-head"><h2 id="modal-title">${title}</h2><button class="icon-btn" data-action="modal-close" aria-label="بستن">${icon('close')}</button></header><div class="modal-body">${html}</div></section></div>`; const el=$('.modal'); el.focus();}
function closeModal() {$('#modal-root').innerHTML='';$('#print-root').innerHTML='';if(previousFocus?.isConnected)previousFocus.focus();}
function patientModal(id) {const p=S.patients.find(p=>p.id===Number(id))||{};showModal(p.id?'دوسیهٔ مریض':'ثبت مریض جدید',`<form id="patient-form" data-id="${p.id||''}"><div class="form-grid">${field('نام','first_name','text',p.first_name,'required maxlength="80"')}${field('تخلص','last_name','text',p.last_name,'required maxlength="80"')}${field('نام پدر','father_name','text',p.father_name,'maxlength="80"')}${field('سن به سال','age','number',p.age,'required min="0" max="130"')}<label class="field">جنسیت<select name="sex"><option value="unknown">نامشخص</option><option value="female" ${p.sex==='female'?'selected':''}>زن</option><option value="male" ${p.sex==='male'?'selected':''}>مرد</option></select></label>${field('وزن به کیلوگرام (اختیاری)','weight_kg','number',p.weight_kg,'min="0.1" max="500" step="0.01"')}${field('تماس','phone','text',p.phone,'dir="ltr" maxlength="40"')}${area('حساسیت‌ها — خالی به معنی عدم حساسیت نیست','allergies',p.allergies,'maxlength="2000"')}${area('سابقهٔ طبی ثبت‌شده','history',p.history,'maxlength="4000"')}</div><div class="form-actions"><button class="btn" type="submit">ذخیرهٔ دوسیه</button>${p.id?`<span class="tag gray en">${p.mrn}</span>`:''}</div></form>`);}
async function patientOptions(selected) {const records=await api('/patients?limit=200');S.patients=records;return `<label class="field full">مریض<select name="patient_id" required><option value="">انتخاب مریض…</option>${records.map(p=>`<option value="${p.id}" ${p.id===Number(selected)?'selected':''}>${esc(p.first_name)} ${esc(p.last_name)} · ${p.mrn}</option>`).join('')}</select><small>آخرین ۲۰۰ مریض؛ برای دوسیهٔ قدیمی از صفحهٔ مریضان جستجو کنید و نسخه را از همان‌جا بسازید.</small></label>`;}
function rxItem() {return `<div class="rx-item">${field('نام کامل دوا و قدرت','name','text','','required maxlength="160" list="workspace-medicine-options" autocomplete="off"')}${field('شکل دوا','form','text','','required maxlength="60" placeholder="تابلیت…"')}${field('دوز — تأیید داکتر','dose','text','','required maxlength="120"')}${field('دفعات مصرف','frequency','text','','required maxlength="120"')}${field('مدت مصرف','duration','text','','required maxlength="120"')}${field('تعداد','quantity','number','1','required min="1" max="10000"')}${field('هدایت / نسبت به غذا','instructions','text','','maxlength="500"')}<button type="button" class="btn ghost" data-action="rx-remove">حذف قلم ${icon('close')}</button></div>`;}
async function rxModal(id) {const existing=S.patients.find(p=>p.id===Number(id));let options=await patientOptions(id);if(existing&&!S.patients.some(p=>p.id===existing.id)) {S.patients.push(existing);options=options.replace('</select>',`<option value="${existing.id}" selected>${esc(existing.first_name)} ${esc(existing.last_name)} · ${existing.mrn}</option></select>`);}showModal('نسخهٔ جدید — پیش‌نویس داکتر',`<form id="rx-form"><div class="form-grid">${options}${area('شکایت مریض','complaint','','required maxlength="4000" placeholder="اعراض را بنویسید…"')}<div id="symptom-suggestions" class="suggestions full"></div>${area('تشخیص ثبت‌شده توسط داکتر','diagnosis','','maxlength="4000"')}${area('توصیه‌ها و یادداشت','notes','','maxlength="4000"')}</div><div class="form-actions between"><h3>اقلام دوا</h3><button type="button" class="btn secondary small" data-action="rx-add">${icon('plus')} افزودن دوا</button></div><p class="tiny">افزودن دوا اختیاری و فقط بر اساس ضرورت بالینی است. سیستم دوز، سیرم یا آمپول تحمیل نمی‌کند.</p><datalist id="workspace-medicine-options"></datalist><div id="rx-items"></div><div class="notice">بازبینی محدود است؛ نام، قدرت، دوز، تداخلات، حساسیت، بارداری و وضعیت کلیه/کبد را از منابع معتبر بررسی کنید.</div><div id="review-result" class="review-result"></div><div class="form-actions"><button class="btn" type="submit">ذخیرهٔ پیش‌نویس</button><button type="button" class="btn secondary" data-action="rx-review">${icon('shield')} بازبینی محدود</button></div></form>`,true);}
function readRx() {const f=$('#rx-form'),data=Object.fromEntries(new FormData(f));return {patient_id:Number(data.patient_id),complaint:data.complaint,diagnosis:data.diagnosis,notes:data.notes,template_id:S.selectedTemplate,items:$$('.rx-item',f).map(row=>Object.fromEntries($$('input',row).map(i=>[i.name,i.name==='quantity'?Number(i.value):i.value])))};}
function printSheet(rx,templateId) {const t=(rx.template_config&&Number(templateId)===rx.template_id?rx.template_config:null)||S.templates.find(t=>t.id===Number(templateId))||S.templates[0]; const h=rx.hospital||S.hospital,p=rx.patient;return `<article class="print-sheet ${templateClass(t)}" style="--accent:${t.studio?.primary||t.color};--wash:${t.studio?.wash||'#fff'}"><header class="print-header"><div class="print-logo">${t.studio?.logo==='heart'?'♡':t.studio?.logo==='monogram'?'AY':'+'}</div><div><h2 class="print-hospital">${esc(h.name)}</h2><div class="print-en">${esc(h.english_name)}</div><div class="tiny">${esc(h.services)}</div></div><div class="print-meta"><span class="en">RX-${String(rx.id).padStart(6,'0')}</span><br>${date(rx.created)}<br>طرح: ${esc(t.name)}</div></header>${t.studio?`<h3 class="print-profile-heading">${esc(t.studio.heading)}</h3>`:''}${rx.status==='draft'?'<div class="print-status">پیش‌نویس — تأیید داکتر ندارد؛ برای تحویل دوا استفاده نشود.</div>':''}<div class="print-patient"><div><b>مریض:</b> ${esc(p.first_name)} ${esc(p.last_name)}</div><div><b>شناسه:</b> <span class="en">${p.mrn}</span></div><div><b>سن / جنس:</b> ${number(p.age)} سال · ${p.sex==='female'?'زن':p.sex==='male'?'مرد':'نامشخص'}</div><div><b>وزن:</b> ${p.weight_kg?number(p.weight_kg)+' kg':'ثبت نشده'}</div><div class="full"><b>حساسیت ثبت‌شده:</b> ${esc(p.allergies)||'ثبت نشده؛ ارزیابی داکتر لازم است'}</div></div><div class="print-complaint"><b>شکایت:</b> ${esc(rx.complaint)}<br><b>تشخیص:</b> ${esc(rx.diagnosis)||'ثبت نشده'}</div><div style="font:25px Georgia,serif;color:var(--accent)">℞</div>${rx.items.length?`<table><thead><tr><th style="width:7%">ردیف</th><th class="medicine-cell">دوا و هدایت مصرف</th><th style="width:18%">شکل</th><th style="width:21%">مدت</th><th style="width:12%">تعداد</th></tr></thead><tbody>${rx.items.map((m,i)=>`<tr><td>${number(i+1)}</td><td><b>${esc(m.name)}</b><br><small>دوز: ${esc(m.dose)} · ${esc(m.frequency)}</small>${m.instructions?`<br><small>${esc(m.instructions)}</small>`:''}</td><td>${esc(m.form)}</td><td>${esc(m.duration)}</td><td>${number(m.quantity)}</td></tr>`).join('')}</tbody></table>`:'<p>دوایی در این نسخه ثبت نشده است.</p>'}<div class="print-complaint"><b>توصیه‌ها:</b> ${esc(rx.notes)||'—'}</div><div class="print-signature"><span>داکتر: ${esc(rx.doctor)}</span><span>${rx.status==='confirmed'?'بازبینی در سیستم تأیید شده':'تأیید نشده'} · محل امضا و مهر: ……………</span></div>${t.studio?`<p class="print-profile-note">${esc(t.studio.footer_note)}</p>`:''}<footer class="print-footer"><div>آدرس: ${esc(h.address)||'ثبت نشده'}<br>ایمیل: <span class="en">${esc(h.email)||'—'}</span></div><div>تماس: <span class="en">${esc(h.phone)||'—'}</span></div><div class="en">${esc(h.website)}<br>ASH NEXUS · RX-${rx.id}</div></footer></article>`;}
function preview(id) {const rx=S.rx.find(r=>r.id===Number(id));if(!rx)return;showModal('مشاهدهٔ نسخه و چاپ A4',`<div class="row between" style="flex-wrap:wrap;margin-bottom:18px"><select id="print-template" ${rx.status==='confirmed'||!can('doctor')||rx.doctor_user_id!==S.user.id?'disabled':''} data-saved-template="${rx.template_id}" data-rx="${rx.id}" aria-label="انتخاب طرح چاپ">${S.templates.map(t=>`<option value="${t.id}" ${rx.template_id===t.id?'selected':''}>${t.name}</option>`).join('')}</select><div class="row">${rx.status==='draft'&&can('doctor')&&rx.doctor_user_id===S.user.id?`<button class="btn secondary small" data-action="rx-edit" data-id="${rx.id}">ویرایش پیش‌نویس</button><button class="btn secondary small" data-action="rx-confirm" data-id="${rx.id}">تأیید بازبینی داکتر</button>`:''}<button class="btn small" data-action="print">${icon('print')} چاپ / ذخیرهٔ PDF</button></div></div><div class="print-preview" id="preview-sheet">${printSheet(rx,rx.template_id)}</div>`,true);$('#print-root').innerHTML=printSheet(rx,rx.template_id);}
async function orderModal() {const kind=S.page;const options=await patientOptions();showModal('درخواست معاینه',`<form id="order-form" data-kind="${kind}"><div class="form-grid">${options}${field('نام آزمایش یا معاینه','title','text','','required maxlength="200"')}</div><div class="form-actions"><button class="btn" type="submit">ثبت درخواست داکتر</button></div></form>`);}
function orderOpen(id) {const o=S.orders.find(o=>o.id===Number(id));showModal('درخواست '+esc(o.title),`<p>${esc(o.patient_name)} · <span class="en">${o.mrn}</span></p>${o.status==='completed'?`<div class="notice teal" style="white-space:pre-wrap">${esc(o.result)}</div>`:can(o.kind)?`<form id="result-form" data-id="${o.id}">${area('نتیجهٔ نهایی — پیش از ثبت بازبینی کنید','result','','required maxlength="8000"')}<div class="notice" style="margin-top:15px">نتیجهٔ ثبت‌شده در این نسخه قابل بازنویسی نیست. تنها نتیجهٔ بررسی‌شدهٔ بخش مسئول را وارد کنید.</div><div class="form-actions"><button type="submit" class="btn">ثبت نتیجه</button></div></form>`:'<div class="notice">در انتظار ثبت نتیجه توسط بخش مسئول.</div>'}`);}
const handlers={
 'modal-close':()=>closeModal(),menu:()=>$('#sidebar').classList.toggle('open'),'navigate-guide':()=>navigate('guide'),
 logout:async()=>{await api('/auth/logout',{method:'POST'});resetLogin();},
 'password-change':()=>showModal('تعویض رمز شخصی',`<form id="password-form"><div class="form-grid">${field('رمز فعلی','current_password','password','','required maxlength="200" autocomplete="current-password"')}${field('رمز جدید (حداقل ۱۲ حرف)','new_password','password','','required minlength="12" maxlength="200" autocomplete="new-password"')}</div><p>با تغییر رمز، تمام نشست‌های این حساب باطل می‌شوند و باید دوباره وارد شوید.</p><div class="form-actions"><button class="btn" type="submit">تغییر رمز و خروج</button></div></form>`),
 'patient-new':()=>patientModal(),'patient-edit':el=>patientModal(el.dataset.id),'rx-new':el=>rxModal(el.dataset.id),
 'rx-add':()=>{if($$('.rx-item').length>=30)throw new Error('حداکثر ۳۰ قلم برای این نسخه.');$('#rx-items').insertAdjacentHTML('beforeend',rxItem());},
 'rx-remove':el=>el.closest('.rx-item').remove(),
 'rx-review':async()=>{if(!$('#rx-form').reportValidity())return;const r=await api('/knowledge/review',{method:'POST',body:JSON.stringify(readRx())});if(!$('#review-result'))return;$('#review-result').innerHTML=`<div class="notice"><b>بازبینی محدود — نه تأیید نسخه</b><div class="readiness-inline">${(r.checklist||[]).map(c=>`<span>${c.recorded?'✓':'○'} ${esc(c.label)}</span>`).join('')}</div><p class="tiny">این مرور کیفیت ثبت است، نه امتیاز خطر یا تأیید حساسیت.</p><ul>${r.warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul>${esc(r.disclaimer)}<p>${r.sources.map(s=>`<a href="${s.url}" target="_blank" rel="noreferrer">${esc(s.name)}</a>`).join(' · ')}</p></div>`;},
 'rx-preview':el=>preview(el.dataset.id),print:()=>window.print(),
 'rx-edit':async el=>{const rx=S.rx.find(r=>r.id===Number(el.dataset.id));if(!rx)return;S.patients.push(rx.patient);await rxModal(rx.patient_id);const f=$('#rx-form');f.dataset.id=rx.id;f.dataset.revision=rx.revision;for(const key of ['complaint','diagnosis','notes'])$(`[name="${key}"]`,f).value=rx[key];S.selectedTemplate=rx.template_id;for(const item of rx.items){$('#rx-items').insertAdjacentHTML('beforeend',rxItem());const row=$$('.rx-item').at(-1);for(const input of $$('input',row))input.value=item[input.name];}},
 'rx-confirm':async el=>{if(!window.confirm('آیا این نسخه را از نظر ضرورت دواها، دوز، حساسیت، تداخلات و وضعیت مریض شخصاً بازبینی کرده‌اید؟'))return;const r=await api(`/prescriptions/${el.dataset.id}/confirm`,{method:'POST',body:JSON.stringify({reviewed:true,revision:S.rx.find(r=>r.id===Number(el.dataset.id)).revision})});S.rx=S.rx.map(x=>x.id===r.id?r:x);preview(r.id);toast('تأیید داکتر ثبت شد.');},
 'template-select':async el=>{const id=Number(el.dataset.id);if(can('admin')){S.hospital=await api('/hospital',{method:'PUT',body:JSON.stringify({...S.hospital,template_id:id})});}S.selectedTemplate=id;$('#page-content').innerHTML=views.templates();toast(can('admin')?'طرح پیش‌فرض در دیتابیس ذخیره شد.':'طرح برای نسخهٔ جدید در همین نشست انتخاب شد.');},
 'medicine-new':()=>showModal('ثبت قلم دوا',`<form id="medicine-form"><div class="form-grid">${field('نام دوا','name','text','','required maxlength="160"')}${field('قدرت','strength','text','','required maxlength="80"')}${field('شکل','form','text','','required maxlength="60"')}${field('موجودی اولیه','stock','number','0','required min="0" max="1000000"')}${field('حد سفارش','reorder','number','10','required min="0" max="1000000"')}</div><div class="form-actions"><button class="btn" type="submit">ثبت قلم</button></div></form>`),
 stock:el=>showModal('تغییر موجودی',`<form id="stock-form" data-id="${el.dataset.id}"><div class="form-grid">${field('تغییر تعداد؛ برای خروج عدد منفی وارد کنید','delta','number','','required min="-1000000" max="1000000"')}${field('علت تغییر؛ بدون اطلاعات مریض','reason','text','','required minlength="3" maxlength="200"')}</div><div class="form-actions"><button class="btn" type="submit">ثبت تغییر</button></div></form>`),
 'order-new':()=>orderModal(),'order-open':el=>orderOpen(el.dataset.id),
 'admit-new':async()=>{const opts=await patientOptions();showModal('ثبت بستری',`<form id="admit-form"><div class="form-grid">${opts}${field('شمارهٔ بستر (۱ تا ۱۰)','bed','number','','required min="1" max="10"')}${area('علت بستری','reason','','required minlength="2" maxlength="2000"')}</div><div class="form-actions"><button class="btn" type="submit">ثبت بستری</button></div></form>`);},
 discharge:el=>showModal('ترخیص مریض',`<form id="discharge-form" data-id="${el.dataset.id}">${area('یادداشت ترخیص داکتر','note','','required minlength="2" maxlength="4000"')}<div class="form-actions"><button class="btn" type="submit">تأیید ترخیص</button></div></form>`),
 'user-new':()=>showModal('حساب کاربری جدید',`<form id="user-form"><div class="form-grid">${field('نام کارمند','name','text','','required minlength="2" maxlength="160"')}${field('نام کاربری انگلیسی','username','text','','required minlength="3" maxlength="120" dir="ltr" pattern="[a-zA-Z0-9@._+\\-]+"')}${field('رمز یکتا (حداقل ۱۲ حرف)','password','password','','required minlength="12" maxlength="200" dir="ltr" autocomplete="new-password"')}<label class="field">نقش<select name="role">${Object.entries(roles).filter(([r])=>r!=='admin').map(([r,n])=>`<option value="${r}">${n}</option>`).join('')}</select></label></div><div class="notice" style="margin-top:17px">مدیر باید هویت و صلاحیت حرفه‌ای کارمند را بررسی کند. رمز را از مسیر امن به کارمند برسانید.</div><div class="form-actions"><button class="btn" type="submit">ساخت حساب</button></div></form>`),
 'user-deactivate':async el=>{if(!confirm('حساب غیرفعال و تمام نشست‌های آن باطل شود؟'))return;await api(`/auth/users/${el.dataset.id}/deactivate`,{method:'POST'});await navigate('users');toast('کاربر غیرفعال شد.');},
 'backup-download':async()=>{if(!confirm('فایل شامل اطلاعات حساس است و رمزگذاری نشده. آن را فقط در محل امن نگهداری می‌کنید؟'))return;const blob=await api('/backups',{method:'POST',download:true});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`ash-backup-${new Date().toISOString().slice(0,10)}.sqlite3`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('فایل بکاپ آماده و دانلود درخواست شد.');},
 'symptom-pick':el=>{const input=$('[name="complaint"]');input.value=input.value.replace(/[^\s،,]*$/,'')+el.dataset.label+'؛ ';$('#symptom-suggestions').innerHTML='';input.focus();}
};
document.addEventListener('click',async event=>{
 const page=event.target.closest('[data-page]');if(page){await navigate(page.dataset.page);return;}
 const el=event.target.closest('[data-action]');if(!el)return;
 const handler=handlers[el.dataset.action];if(!handler)return;
 el.disabled=true;try{await handler(el);}catch(e){toast(e.message,true);}finally{el.disabled=false;}
});
document.addEventListener('submit',async event=>{
 const f=event.target;if(f.dataset.workspace==='true')return;event.preventDefault();const data=Object.fromEntries(new FormData(f)),submit=$('[type="submit"]',f);if(submit)submit.disabled=true;
 try {
   if(f.id==='login-form'){try{const r=await api('/auth/login',{method:'POST',body:JSON.stringify(data)});S.user=r.user;S.csrf=r.csrf;await startSession();}catch(e){$('#login-error').innerHTML=`<div class="error">${esc(e.message)}</div>`;}return;}
   if(f.id==='password-form'){await api('/auth/password',{method:'POST',body:JSON.stringify(data)});resetLogin();toast('رمز عوض شد؛ با رمز جدید وارد شوید.');return;}
   if(f.id==='patient-search'){const rows=await api(`/patients?q=${encodeURIComponent(data.q)}`);S.patients=rows;$('#patient-rows').innerHTML=patientRows();$('#patient-empty').innerHTML=rows.length?'':empty('نتیجه‌ای یافت نشد','نام یا شناسهٔ دیگری را جستجو کنید.');return;}
   if(f.id==='patient-form'){data.age=Number(data.age);data.weight_kg=data.weight_kg?Number(data.weight_kg):null;await api(f.dataset.id?`/patients/${f.dataset.id}`:'/patients',{method:f.dataset.id?'PUT':'POST',body:JSON.stringify(data)});closeModal();await navigate('patients');toast('دوسیه در دیتابیس ذخیره شد.');return;}
   if(f.id==='rx-form'){const body=readRx();if(f.dataset.id)body.revision=Number(f.dataset.revision);const r=await api(f.dataset.id?`/prescriptions/${f.dataset.id}`:'/prescriptions',{method:f.dataset.id?'PUT':'POST',body:JSON.stringify(body)});await navigate('rx');preview(r.id);toast('پیش‌نویس ذخیره شد؛ هنوز تأیید داکتر ندارد.');return;}
   if(f.id==='hospital-form'){data.template_id=Number(data.template_id);S.hospital=await api('/hospital',{method:'PUT',body:JSON.stringify(data)});S.selectedTemplate=data.template_id;toast('پروفایل ذخیره شد.');return;}
   const routes={
     'medicine-form':['/medicines','pharmacy'], 'stock-form':[`/medicines/${f.dataset.id}/stock`,'pharmacy'],
     'order-form':['/orders',f.dataset.kind], 'result-form':[`/orders/${f.dataset.id}/result`,S.page],
     'admit-form':['/admissions','beds'],'discharge-form':[`/admissions/${f.dataset.id}/discharge`,'beds'],
     'user-form':['/auth/users','users']
   };
   if(routes[f.id]) {if(f.id==='medicine-form'){data.stock=Number(data.stock);data.reorder=Number(data.reorder);}if(f.id==='stock-form')data.delta=Number(data.delta);if(f.id==='order-form'){data.patient_id=Number(data.patient_id);data.kind=f.dataset.kind;}if(f.id==='admit-form'){data.patient_id=Number(data.patient_id);data.bed=Number(data.bed);}await api(routes[f.id][0],{method:'POST',body:JSON.stringify(data)});closeModal();await navigate(routes[f.id][1]);toast('عملیات در دیتابیس ثبت شد.');}
 } catch(e){toast(e.message,true);}finally{if(submit)submit.disabled=false;}
});
document.addEventListener('change',async event=>{if(event.target.id==='activation-file'){try{const file=event.target.files[0];if(!file)return;if(file.size>20000)throw new Error('فایل بیش از حد بزرگ است.');await api('/activation',{method:'POST',body:JSON.stringify({license:await file.text()})});await navigate('settings');toast('فعال‌سازی تمدید شد.');}catch(error){toast(error.message,true);}return;}if(event.target.id==='print-template'){
 const select=event.target,rx=S.rx.find(r=>r.id===Number(select.dataset.rx)),actor=S.user;
 if(!rx||rx.status!=='draft'||rx.doctor_user_id!==actor?.id)return;
 const template_id=Number(select.value);if(template_id===rx.template_id)return;
 select.disabled=true;const buttons=$$('[data-action=rx-confirm],[data-action=rx-edit],[data-action=print]');buttons.forEach(b=>b.disabled=true);
 try{const updated=await api(`/prescriptions/${rx.id}`,{method:'PUT',body:JSON.stringify({patient_id:rx.patient_id,complaint:rx.complaint,diagnosis:rx.diagnosis,notes:rx.notes,items:rx.items,template_id,revision:rx.revision})});
 if(S.user!==actor)return;S.rx=S.rx.map(r=>r.id===updated.id?updated:r);S.selectedTemplate=updated.template_id;
 if(select.isConnected){preview(updated.id);$('#print-template').focus();}
 }catch(error){if(S.user===actor){toast(error.message,true);if(select.isConnected)select.value=String(rx.template_id);}}
 finally{if(select.isConnected)select.disabled=false;buttons.forEach(b=>{if(b.isConnected)b.disabled=false;});}
 }});
let symptomTimer;
document.addEventListener('input',event=>{if(event.target.name!=='complaint')return;const input=event.target;clearTimeout(symptomTimer);const query=input.value.trim().split(/[\s،,؛]/).pop();if(!query){$('#symptom-suggestions').innerHTML='';return;}symptomTimer=setTimeout(async()=>{try{const r=await api(`/knowledge/symptoms?q=${encodeURIComponent(query)}`);if(!input.isConnected)return;$('#symptom-suggestions').innerHTML=r.matches.map(s=>`<button type="button" data-action="symptom-pick" data-label="${esc(s.label)}">${esc(s.label)}${s.match==='possible_typo'?' · شباهت تایپی؛ تأیید کنید':''}</button>`).join('');}catch{}},250);});
document.addEventListener('keydown',event=>{const modal=$('.modal');if(!modal)return;if(event.key==='Escape')closeModal();if(event.key==='Tab'){const focusable=$$('button,input,select,textarea,a[href]',modal).filter(el=>!el.disabled);const first=focusable[0],last=focusable.at(-1);if(!first)return;if(event.shiftKey&&(document.activeElement===first||document.activeElement===modal)){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});
async function startSession(){const h=await api('/hospital');let t=[];if(can('admin','doctor','reception'))t=await api('/templates');S.hospital=h;S.templates=t;S.selectedTemplate=h.template_id;if(window.ASHWorkspace)await window.ASHWorkspace.init();if(window.ASHProfessional)await window.ASHProfessional.init();shell();await navigate('dashboard');}
(async()=>{try{const r=await api('/auth/me');S.user=r.user;S.csrf=r.csrf;await startSession();}catch{resetLogin();}})();
